package com.bank.security;

import java.util.*;
import java.util.logging.*;

public class LongestUniqueDemo {
    private static final Logger log = Logger.getLogger(LongestUniqueDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TokenEntropyAnalyzer analyzer = new TokenEntropyAnalyzer();

        String token = "abcabcbb"; // classic example
        int len = analyzer.longestDistinctRun(token);
        log.info(() -> "Longest distinct run in '" + token + "': " + len);
    }
}

