class TokenEntropyAnalyzer {
    private static final Logger log = Logger.getLogger(TokenEntropyAnalyzer.class.getName());

    // Variable window + last-seen map. O(n) time, O(min(n,alphabet)) space.
    int longestDistinctRun(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (last.containsKey(c) && last.get(c) >= left) {
                left = last.get(c) + 1;   // jump past the previous copy inside window
            }
            last.put(c, right);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

